import 'package:equatable/equatable.dart';

/// A suggestion to promote a frequently-sold quick sale item into the catalog.
///
/// Generated by [QuickSaleSuggestionService] from aggregated `sale_items` rows
/// where `is_quick_sale = true`. The [name] is the human-readable label the
/// cashier entered, [timesSold] is the count over the lookback window, and
/// [avgPrice] is the average unit price across those sales.
class QuickSaleSuggestion extends Equatable {
  final String name;
  final int timesSold;
  final double avgPrice;

  const QuickSaleSuggestion({
    required this.name,
    required this.timesSold,
    required this.avgPrice,
  });

  @override
  List<Object> get props => [name, timesSold, avgPrice];
}
